INSERT INTO `gestion_hcp` (`id`, `ID_hcp`, `description_hcp`, `presentation_hcp`, `creation_hcp`, `Image_hcp`, `enquete_link`, `publication_link`, `donne_reg_link`, `rapp_hcp_link`, `contact_hcp_link`, `gps_link`, `site_link`, `Zone`) VALUES
(1, 'alhoceima', 'Le Haut-Commissariat au Plan à Al Hoceima accompagne le développement de la région du Rif à travers la production de données statistiques fiables au service des citoyens et des décideurs.', 'La Direction Provinciale d\'Al Hoceima est la représentation du Haut-Commissariat au Plan dans la région. Elle assure la mise en œuvre des programmes s', 2003, , '', 'https://www.hcp.ma/reg-alhoceima/Publications_r4.html', 'https://www.hcp.ma/reg-alhoceima/Annuaires-Statistiques-de-la-Province-d-Al-Hoceima_a144.html', 'https://www.hcp.ma/reg-alhoceima/Monographies-provinciales-d-Al-Hoceima_a37.html', 'https://www.hcp.ma/reg-alhoceima/Monographies-provinciales-d-Al-Hoceima_a37.html', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1293.083632720037!2d-3.9393777411242654!3d35.247139498537166!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xd7431de9bb3d30b%3A0xf61f5c8335850773!2sHaut%20Commissariat%20au%20Plan%20Al%20hoceima!5e0!3m2!1sfr!2sma!4v1785280133783!5m2!1sfr!2sma', 'https://www.hcp.ma/reg-alhoceima/', 'Tanger-Tétouan-Al Hoceïma');
INSERT INTO `gestion_hcp` (`id`, `ID_hcp`, `description_hcp`, `presentation_hcp`, `creation_hcp`, `Image_hcp`, `enquete_link`, `publication_link`, `donne_reg_link`, `rapp_hcp_link`, `contact_hcp_link`, `gps_link`, `site_link`, `Zone`) VALUES
(2, 'tanger', 'Le Haut-Commissariat au Plan à Tanger accompagne le développement de la région Tanger-Tétouan-Al Hoceïma à travers la production de données statistiques fiables au service des citoyens et des décideurs.', 'La Direction Provinciale de Tanger est la représentation du Haut-Commissariat au Plan dans la région. Elle assure la mise en œuvre des programmes statistiques, la collecte de données de qualité et leur diffusion pour accompagner les politiques publiques et le développement socio-économique de la région.', 2003, , 'https://www.hcp.ma/region-tanger/#mw999', 'https://www.hcp.ma/region-tanger/#mw999', 'http://bds-tanger.hcp.ma/', '', 'hcp.dr.tanger@hcp.ma', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3236.9880170547667!2d-5.807298211145014!3d35.7756707!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xd0b80a7f68c9233%3A0x294671ccf2c8ee4d!2sDirection%20R%C3%A9gionale%20du%20Haut%20Commissariat%20au%20Plan!5e0!3m2!1sfr!2sma!4v1785323267171!5m2!1sfr!2sma', 'https://www.hcp.ma/region-tanger/', 'Tanger-Tétouan-Al Hoceïma');
INSERT INTO `gestion_hcp` (`id`, `ID_hcp`, `description_hcp`, `presentation_hcp`, `creation_hcp`, `Image_hcp`, `enquete_link`, `publication_link`, `donne_reg_link`, `rapp_hcp_link`, `contact_hcp_link`, `gps_link`, `site_link`, `Zone`) VALUES
(3, 'rabat', 'Le Haut-Commissariat au Plan à Rabat accompagne le développement de la région Rabat-Salé-Kénitra à travers la production de données statistiques fiables au service des citoyens et des décideurs.', 'La Direction Régionale de Rabat-Salé-Kénitra est la représentation du Haut-Commissariat au Plan dans la région. Elle assure la mise en œuvre des programmes statistiques, la collecte de données de qualité et leur diffusion pour accompagner les politiques publiques et le développement socio-économique de la région.', 2003, , NULL, 'https://www.hcp.ma/region-rabat/_a79.html?preview=1', 'http://www.bds-rabat.hcp.ma/fr/', 'https://www.hcp.ma/region-rabat/_a79.html?preview=1', 'http://www.bds-rabat.hcp.ma/fr/contact#', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d52930.92126328208!2d-6.888355589682988!3d33.98784380268366!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xda76b9082509bcf%3A0x5408a15003ab6ff1!2sDirection%20R%C3%A9gionale%20du%20Haut%20Commissariat%20au%20Plan%20Rabat%20Sal%C3%A9%20K%C3%A9nitra!5e0!3m2!1sfr!2sma!4v1785324431270!5m2!1sfr!2sma', 'https://www.hcp.ma/region-rabat/', 'Rabat-Salé-Kénitra');
INSERT INTO `gestion_hcp` (`id`, `ID_hcp`, `description_hcp`, `presentation_hcp`, `creation_hcp`, `Image_hcp`, `enquete_link`, `publication_link`, `donne_reg_link`, `rapp_hcp_link`, `contact_hcp_link`, `gps_link`, `site_link`, `Zone`) VALUES
