INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(6, 'PB-001', , 'Dynamiques Démographiques et Socio-économiques de Tanger Tétouan Al Hoceima 2025', 'Rapports et études', 'Publié', '2026-08-14', 'La Direction régionale a le plaisir de présenter la Publication « Dynamiques démographiques et socio-économiques de la région Tanger-Tétouan-Al Hoceima », édition 2025, dont l’objectif est d’offrir aux différents utilisateurs - décideurs, planificateurs, acteurs locaux et régionaux, investisseurs, étudiants, et autres - une étude actualisée mettant en lumière les potentialités de la région à travers plusieurs dimensions : démographiques, sociales, économiques et infrastructurelles. La réalisation de cette étude a été rendue possible grâce à la disponibilité d’indicateurs récents et de statistiques sectorielles provenant de multiples sources d’information. La principale nouveauté de cette édition réside dans l’exploitation de la Base de Données Statistique Régionale (BDSR) de Tanger-Tétouan-Al Hoceima, mise en ligne depuis l’année 2021. Comptant près de 800 indicateurs regroupés en 24 thèmes, cette plateforme constitue désormais un outil de référence pour l’élaboration de toute étude ou analyse régionale.', 'uploads/1786739859_PB-002.pdf', 1);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(7, 'PB-002', , 'Monographie préfectorale de Tanger 2022', 'Rapports et études', 'Publié', '2026-08-14', 'La direction régionale du Haut Commissariat au Plan de Tanger-Tétouan-Al Hoceima a le plaisir de mettre à la disposition des acteurs régionaux et locaux la nouvelle monographie préfectorale de Tanger-Assilah. \r\nL’élaboration de la présente étude s’appuie essentiellement sur les statistiques sous\r\nproduites des différents secteurs économiques. Ces informations sont fournies par la Base de Données Statistiques de Tanger consultable au lien suivant : www.bds-tanger.hcp.ma  \r\nA cette occasion, nous remercions vivement les différents points focaux de la CoRéCoS (commission régionale de la coordination statistique) qui contribuent activement à l\'alimentation et la mise à jour de la BDS-Tanger.', NULL, 0);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(8, 'PB-003', , 'Monographie régionale 2020 de TTA', 'Rapports et études', 'Publié', '2026-08-15', 'La monographie de la région de Tanger Tétouan Al Hoceima se veut de présenter les potentialités de la région  à travers une batterie d\'indicateurs démographiques, sociaux, économiques et  infrastructurels…  issus de différentes sources d’information et surtout de la base de données statistique régionale (BDSR) de la RTTA, qui englobe plus de 300 indicateurs issus des recensements et des enquêtes statistiques effectuées par le HCP ainsi que les statistiques administratives sous produites par les différents départements ministériels.', 'uploads/1786742808_PB-003.pdf', 10);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(9, 'PB-004', , 'Monographie provinciale de Tétouan 2019', 'Rapports et études', 'Publié', '2026-08-15', 'Cette monographie se veut de présenter la province de Tétouan à travers sa population, son milieu naturel, son infrastructure de base, ainsi qu’à travers les principaux secteurs économiques et sociaux.', 'uploads/1786743143_PB-004.pdf', 0);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(10, 'PB-005', , 'Monographie provinciale de Chefchaouen 2018', 'Rapports et études', 'Publié', '2026-08-15', 'La monographie de la province de Chefchaouen se veut de présenter la province de Chefchaouen à travers sa population, son milieu naturel, son infrastructure de base, ainsi qu’à travers les principaux secteurs économiques et sociaux.', 'uploads/1786743343_PB-005.pdf', 3);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(11, 'PB-006', , 'Monographie provinciale d\'Al Hoceima 2017', 'Rapports et études', 'Publié', '2026-08-15', 'La monographie de la province d\'Al Hoceima est une présentation synthétique et dynamique de la carte d\'identité de la province d’Al Hoceima la plus complète et la plus significative possible qui rendrait compte tant des potentialités objectives de la province que des contraintes matérielles, humaines et sociales.', 'uploads/1786743463_PB-006.pdf', 3);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(12, 'PB-007', , 'الإحتفال بالذكرى 20 لانطلاق المبادرة الوطنية للتنمية البشرية', 'Autres documents', 'Publié', '2026-08-14', 'الإحتفال بالذكرى 20 لانطلاق المبادرة الوطنية للتنمية البشرية\r\nشاركت المديرية الإقليمية للتخطيط بالحسيمة في فعاليات حفل تخليد الذكرى العشرون لانطلاق المبادرة الوطنية للتنمية البشرية المنظم تحت رئاسة السيد عامل إقليم الحسيمة يومه الخميس 22 ماي 2025 بمقر عمالة الحسيمة، حيث تم عرض حصيلة إنجازات المبادرة خلال الفترة الممتدة بين 2005 و2025.  وفي نفس الإطار أشرف السيد العامل على افتتاح المعرض الإقليمي للمنتجات المجانية بساحة محمد السادس بمدينة الحسيمة والمنظم احتفاء بالذكرى العشرين للمبادرة الوطنية للتنمية البشرية،', NULL, 0);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(13, 'PB-008', , 'Al Hoceima en chiffres 2024', 'Rapports et études', 'Publié', '2026-08-14', '', 'uploads/1786743877_PB-008.pdf', 0);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(14, 'PB-009', , 'عرض حول نتائج وخلاصات الإحصاء العام للسكان والسكنى 2024', 'Rapports et études', 'Publié', '2026-08-14', ' عقد السيد عامل صاحب الجلالة على عمالة إقليم الحسيمة، السيد حسن الزيتوني، يومه الثلاثاء 20 ماي 2025 لقاء موسعا بمقر العمالة والذي نظم في إطار تقديم نتائج الإحصاء العام للسكان والسكنى 2024، بحضور كل من السيد الكاتب العام للعمالة والسيد رئيس المجلس الإقليمي لإقليم الحسيمة والسادة رؤساء المصالح الأمنية والعسكرية والسادة رجال السلطة المحلية والسادة رؤساء الجماعات الترابية والسيدات والسادة ممثلي المؤسسات العمومية والمصالح اللاممركزة للدولة. وفي هذا الإطار، قدمت السيدة المديرة الإقليمية للتخطيط بالحسيمة عرضا حول نتائج وخلاصات الإحصاء العام للسكان والسكنى 2024 من الجانب الديموغرافي والرأسمال البشري والتحديات الاجتماعية والاقتصادية وظروف السكن بالإقليم. وقد أكد السيد العامل في كلمته بالمناسبة على الأهمية البالغة لعملية الإحصاء العام من حيث المساهمة في التشخيص وإعداد وتتبع وتقييم المخططات والبرامج التنموية الوطنية والجهوية والإقليمية والمحلية.', NULL, 0);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(15, 'PB-010', NULL, 'The Consumer Price Index - September 2021', 'Rapports et études', 'Publié', '2026-08-14', '', 'uploads/1786744223_PB-010.pdf', 0),
(16, 'PB-011', NULL, 'The Consumer Price Index - September 2022', 'Notes et analyses', 'Publié', '2026-08-14', 'Cette note présente l’évolution de l’Indice des Prix à la Consommation (IPC) pour le mois de septembre 2021. Elle analyse les variations mensuelles et annuelles, avec un focus sur les principaux postes de dépenses (alimentation, énergie, transport, etc.) et les disparités régionales. L’indice national a enregistré une hausse de 0,7 % par rapport au mois d’août 2021 et de 1,2 % sur un an. Les plus fortes augmentations ont été relevées à Fès et Settat (+1,5 %), tandis qu’une baisse de -1,1 % a été observée à Al Hoceima.', NULL, 0);
INSERT INTO `publication` (`id`, `ID_pub`, `Images`, `Titre_pub`, `Categorie`, `Statut`, `date_pub`, `description`, `link_pub`, `nbre_tel`) VALUES
(17, 'PB-012', , 'Annuaires Statistiques de la Province d\'Al Hoceima', 'Notes et analyses', 'Publié', '2026-08-14', 'La Direction Provinciale du Plan à Al Hoceima ambitionne, à travers ce document, de mettre à la disposition de l’ensemble des utilisateurs de l’information statistique, des données leur permettant une connaissance claire et précise de l’environnement démographique et socio-économique et partant une meilleure évaluation des politiques publiques au niveau provincial et local.\r\nL’annuaire statistique provincial renferme, en plus des données collectées auprès des administrations\r\npubliques, semi-publiques et du secteur privé ayant trait à leurs activités, celles émanant des résultats du Recensement Général de la Population et de l’Habitat, des enquêtes et études statistiques.', 'uploads/1786744461_PB-012.pdf', 0);
