INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(5, 'ST-001', , 'Situation du marché du travail au Maroc au deuxième trimestre de 2026 à partir de la nouvelle enquête sur la main-d’œuvre (EMO2026)', 'Le Haut-Commissariat au Plan (HCP) présente la situation du marché du travail au deuxième trimestre 2026, issue de la nouvelle Enquête sur la Main-d’œuvre (EMO2026). Rappelons qu\'il s\'agit de la première enquête d\'une nouvelle génération d\'enquêtes sur le marché du travail au Maroc, conçue conformément aux récentes normes internationales adoptées lors des 19e, 20e et 21e Conférences Internationales des Statisticiens du Travail (CIST) de l\'Organisation Internationale du Travail (OIT). Elle se substitue à l\'Enquête Nationale sur l\'Emploi (ENE). \r\n \r\nPrincipaux changements méthodologiques et conceptuels\r\nLes principaux changements adoptés par ce nouveau dispositif se déclinent en trois axes :\r\nAxe 1 – Mise à jour conceptuelle : les principales évolutions introduites par le nouveau cadre conceptuel s’articulent autour de trois axes majeurs :\r\n• La redéfinition de l’emploi : L’EMO 2026 considère désormais comme emploi uniquement le travail exercé contre rémunération ou en vue d’un profit. A titre d’exemple, les personnes exerçant des activités destinées principalement à l’autoconsommation au sein d’unités non marchandes sont désormais classées dans la production pour usage propre, et non plus dans l’emploi.\r\n• L’adoption du chômage strict : le taux de chômage strict remplace désormais le taux de chômage mesuré dans le cadre de l’ENE. Plus restrictif, il ne considère comme chômeuses que les personnes sans emploi, disponibles pour travailler et recherchant activement un emploi. Il e', 'Marché du travail', 'Publié', '2026-08-12', 'uploads/1786805033_ST-001.pdf', 1);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(6, 'ST-002', , 'Note à l’occasion de la journée mondiale contre le travail des enfants, 2026', 'A cette occasion, le Haut-Commissariat au Plan présente les traits saillants des caractéristiques des enfants au travail selon les données de l’enquête nationale sur l’emploi de 2025.\r\n\r\nLes enfants au travail au Maroc\r\nEn 2025, près de 103.000 enfants âgés de 7 à 17 ans étaient engagés dans une activité économique. La part des enfants au travail est de 1,3% des enfants de cette tranche d’âge, 2,4% en milieu rural et 0,5% en milieu urbain.\r\n\r\nLe phénomène des enfants au travail est plus répandu parmi les garçons que parmi les filles, et il est souvent associé à la déscolarisation. Ainsi, 86,2% des enfants au travail sont de sexe masculin, 89,8% ont entre 15 et 17 ans et 76,2% vivent en milieu rural.\r\nDe plus, 11% parmi eux sont encore scolarisés, 88% ont quitté l’école et 1% ne l’ont jamais fréquentée.\r\n\r\nLes enfants au travail se concentrent au secteur de l’agriculture\r\nLe phénomène reste concentré dans certains secteurs économiques et diffère selon le milieu de résidence.\r\nAinsi, en milieu rural, ils sont 69,1% à travailler dans «l’agriculture, forêt et pêche». En zones urbaines, les «services», avec 51,2%, et l’»industrie», avec 28,4%, sont les principaux secteurs employeurs d’enfants.\r\n\r\nPrès de six enfants au travail sur dix en milieu rural sont des aides familiales (57,9%) et 32,6% des salariés. En milieu urbain, 58,6% des enfants au travail sont des salariés, 25% des apprentis et 13,5% des aides familiales.\r\n\r\nPrès de six enfants au travail sur dix accomplissent des tr', 'Marché du travail', 'Publié', '2026-08-13', 'uploads/1786805417_ST-002.pdf', 1);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(7, 'ST-003', , 'Situation du marché du travail au Maroc au premier trimestre de 2026 à partir de la nouvelle enquête sur la main-d’œuvre (EMO2026)', 'La nouvelle Enquête sur la main-d\'œuvre (EMO2026) constitue la première enquête d\'une nouvelle génération d\'enquêtes sur le marché du travail au Maroc, conçue conformément aux récentes normes internationales adoptées lors des 19e, 20e et 21e Conférences internationales des statisticiens du travail (CIST) de l\'Organisation internationale du Travail (OIT). Elle se substitue à l\'Enquête nationale sur l\'emploi (ENE).\r\n\r\nPrincipaux changements méthodologiques et conceptuels\r\nLes principaux changements adoptés par ce nouveau dispositif se déclinent en trois axes :\r\n \r\nAXE 1\r\nMise à jour conceptuelle \r\nLes principales évolutions introduites par le nouveau cadre conceptuel s’articulent autour de trois axes majeurs :\r\nLa redéfinition de l’emploi, désormais limité aux activités exercées contre rémunération ou en vue d’un profit ;\r\nL’adoption du chômage au sens strict, afin de mieux mesurer la pression immédiate exercée sur le marché du travail ;\r\net l’élargissement de la mesure de la sous-utilisation de la main-d’œuvre, intégrant également  le sous-emploi lié à la durée du travail et la main-d’œuvre potentielle.\r\n \r\nA noter que les résultats de l’EMO2026 ne sont pas directement comparables aux séries antérieures de l’ENE, en raison de ruptures conceptuelles :\r\nL’emploi : L’EMO 2026 considère désormais comme emploi uniquement le travail exercé contre rémunération ou en vue d’un profit. A titre d’exemple, les personnes exerçant des activités destinées principalement à l’autoconsommation ', 'Marché du travail', 'Publié', '2026-08-15', 'uploads/1786805619_ST-003.pdf', 15);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(8, 'ST-004', , 'Informalité, genre et vieillissement : inégalités cumulatives et effets intergénérationnels, Mai 2026', 'Le marché du travail marocain produit, au fil du cycle de vie, des inégalités qui se répercutent durablement sur les droits à pension. Les trajectoires d’emploi informel, la faible participation féminine au marché du travail et les interruptions d’activité liées aux charges familiales réduisent progressivement les capacités d’accumulation contributive des femmes. Le vieillissement démographique transforme ensuite ces déséquilibres accumulés en écarts de protection observés à l’âge de la retraite. \r\n\r\nTrois dynamiques structurent ce système. L’informalité maintient une large part des actifs occupés dans des positions qui ne génèrent que peu ou pas de droits contributifs. La participation féminine reste contenue autour de 20 %, et plus des deux tiers des femmes occupées travaillent dans l\'informel. Le vieillissement démographique transforme une base contributive déjà étroite en une contrainte croissante pour le financement des droits sociaux, et reporte sur les femmes les charges de soin qui réduisent leur disponibilité pour l\'emploi formel. Ces trois mécanismes se renforcent mutuellement et conditionnent la trajectoire des droits que percevront les cohortes actuellement actives.\r\n\r\nLe rapport mobilise un modèle dynamique d’équilibre général à générations imbriquées afin d’analyser ces mécanismes cumulatifs et de simuler, à l’horizon 2070, huit scénarios. Ces derniers couvrent des chocs agissant sur l\'offre de travail, à travers le capital humain, la participation féminine et l', 'Marché du travail', 'Publié', '2026-08-16', 'uploads/1786805748_Informalit____genre_et_vieillissement___in__galit__s_cumulatives_et_effets_interg__n__rationnels__rapport_analytique__Mai_2026__version_Fr_.pdf', 2);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(9, 'ST-005', , 'Note d\'information sur les comptes régionaux de l\'année 2024', 'Contexte économique national :\r\n\r\nEn 2024, l\'économie marocaine a aﬃché une croissance de 4,4%, avec un Produit Intérieur Brut (PIB) en volume qui a atteint 1550,45 milliards de DH. Aux prix courants, le PIB s\'est établi à 1614,57 milliards de DH, soit une augmentation de 8,7% par rapport à 2023. \r\nLa présente note porte sur la croissance du Produit Intérieur Brut par région, la contribution de chaque région à la création de richesse selon les secteurs d\'activité, le PIB par habitant, ainsi que les dépenses de consommation finale des ménages.\r\n\r\nCroissance économique régionale :\r\n\r\nL’année 2024 a mis en évidence des disparités notables dans la croissance du PIB en volume entre les différentes régions du Maroc. Alors que la croissance moyenne nationale s’est établie à 4,4%, les performances régionales ont été contrastées. Ces écarts traduisent des dynamiques économiques locales différenciées, liées notamment au poids des activités sectorielles, au niveau de diversification économique et à la capacité de chaque territoire à contribuer à la croissance nationale. Par ailleurs, la contribution à la croissance demeure inégalement répartie, reflétant le poids économique plus important de certaines régions dans la création de richesse nationale.', 'Economie', 'Publié', '2026-08-16', 'uploads/1786805861_Les_comptes_r__gionaux._Produit_int__rieur_brut_et_d__penses_de_consommation_finale_des_m__nages_2024__version_fran__aise_.pdf', 0);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(10, 'ST-006', , 'Le HCP réitère son appel aux entreprises à souscrire à la plateforme digitale d\'échange d\'informations sur la conjoncture économique nationale', 'Dans le cadre de son programme de transformation digitale, le Haut-Commissariat au Plan a mis en place, au troisième trimestre 2021, une plateforme de collecte de données statistiques à distance pour les enquêtes de conjoncture auprès des entreprises. Ce nouveau mode de collecte utilisera le canal \"internet\" et mettra à la disposition des entreprises des formulaires en ligne qui remplaceront ainsi les anciens questionnaires \"papier\".\r\n\r\nCe nouveau dispositif permettra un gain de temps, une interactivité continue avec les entreprises et répondra par la même occasion aux contraintes de distanciations sanitaires. Il est à signaler en outre que la plateforme mise en place est dotée de mécanismes de sécurité efficaces afin de garantir la confidentialité des données recueillies.\r\n\r\nL’opération de collecte via ce mode lancée en Juillet dernier, limitée à un périmètre restreint, est maintenant élargie à l’ensemble de l’échantillon d’entreprises industrielles, objet des enquêtes trimestrielles de conjoncture, et sera étendue dans un second temps aux entreprises des secteurs des services, du commerce et de la construction échantillonnées dans le cadre de cette enquête. La généralisation de ce dispositif à l’ensemble des enquêtes entreprises, prévue par le programme de digitalisation du HCP, dépendra du rythme d’adhésion des entreprises à ce nouveau mode.\r\n\r\nIl est porté à la bienveillante attention des entreprises qu’une capsule vidéo expliquant toutes les modalités de cette opération ', 'Economie', 'Publié', '2026-08-11', 'uploads/1786805993_communique_operation_cawi_appel_aux_entreprises_ar.doc', 0);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(11, 'ST-007', , 'Les Cahiers du Plan N° 57 - Juillet 2024', '\r\nLes secteurs d’activité ne se valent pas en termes d’importance dans une économie particulière. L’approche la plus communément utilisée pour évaluer cette importance, connue sous l\'appellation de « secteurs clés » ou « key sectors », se fonde exclusivement sur les multiplicateurs de demande et d’offre. Une autre approche employée est la méthode de l’extraction hypothétique, qui consiste à jauger l’importance d’un secteur en simulant son élimination du circuit économique. Ces approches sont cependant limitées car elles s’avèrent partielles vu leur caractère unidimensionnel.\r\n\r\nDe même, elles ne permettent pas de nuancer suffisamment entre les secteurs qui ne manifestent pas de comportement caractérisé, ce qui débouche sur des regroupements moins pertinents. C’est dans ce contexte que nous proposons une cartographie des secteurs d’activité basée sur une approche novatrice sous forme d’analyse multicritère (analyse de données et classification) basée sur une vingtaine d’indicateurs sectoriels dont les linkages. Cette approche nous a permis de dégager cinq critères de segmentation pertinents et intelligibles, mais aussi suffisants pour comprendre la structure sectorielle de l’économie marocaine. Dans le sillage de cette investigation, la palette sectorielle du Maroc (en 27 branches initialement retenues) peut être segmentée en sept clusters d’activité qui se caractérisent par une homogénéité interne et une hétérogénéité externe. Cette segmentation peut s’avérer utile pour le di', 'Economie', 'Publié', '2026-04-11', 'uploads/1786806118_Les_Cahiers_du_Plan_N___57_-_Juillet_2024.pdf', 1);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(12, 'ST-008', , 'L’UNFPA et le HCP explorent les enjeux de la fécondité à l’occasion de la Journée mondiale de la population', '\r\nRabat, le 9 juillet 2025 – A l’occasion de la Journée Mondiale de la Population, célébrée le 11 juillet de chaque année, le Fonds des Nations Unies pour la Population (UNFPA) au Maroc et le Haut-Commissariat au Plan (HCP) ont conjointement organisé un évènement pour présenter le Rapport sur l’état de la population mondiale, édité cette année par l’UNFPA.\r\n\r\nS’appuyant sur des travaux de recherche universitaire et sur de nouvelles données issues d’une enquête UNFPA/YouGov réalisée dans 14 pays, dont le Maroc, ce rapport intitulé \"La véritable crise de la fécondité : La quête du libre arbitre en matière de procréation dans un monde en mutation\" met en lumière une réalité préoccupante : des millions de personnes à travers le monde ne sont pas en mesure d’avoir le nombre d’enfants qu’elles souhaitent, non par rejet de la parentalité, mais en raison d’obstacles économiques et sociaux.\r\n \r\nCet événement a été l’occasion de nourrir la réflexion autour des dynamiques démographiques contemporaines et des défis qu’elles soulèvent, à la lumière notamment des résultats du 7ème Recensement Général de la Population et de l’Habitat (RGPH) réalisé par le HCP en septembre 2024.\r\n', 'Population & démographie', 'Publié', '2026-07-11', NULL, 0);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(13, 'ST-009', , 'Note sur le niveau et la tendance de la fécondité au Maroc', 'La transition de la fécondité est le passage d’un niveau de fécondité élevé à une fécondité basse jusqu’à atteindre le taux de remplacement des générations, qui peut être même dépassé. Une fois ce processus amorcé, la baisse a tendance à s’opérer sans interruption. Ce schéma classique, certes vérifié dans le cas de bien de pays, n’est, cependant, pas universellement observé.\r\n\r\n\r\nNote sur le niveau et la tendance de la fécondité au Maroc\r\nAmorce d’une hausse de la fécondité ?\r\n\r\nDepuis le début des années soixante la fécondité a considérablement baissé. Elle est passée de 7,20 enfants par femme en 1962 à 3,28 en 1994, à 2,47 en 2004 et à 2,19 en 2010 et a connu une faible hausse, passant à 2,20 enfants par femme en 2014, soit pratiquement une stagnation. En milieu rural, la fécondité a baissé de 6,91 en 1962 à 4,25 en 1994, ensuite à 3,06 en 2004, puis à 2,70 en 2010 et à 2,55 en 2014. Tandis qu’en milieu urbain, elle a baissé respectivement de 7,77 à 2,56, puis 2,05 et 1,80 avant une légère reprise, à 2,01 enfants par femme, enregistrée en 2014.\r\n\r\nToutefois, la baisse a été interrompue, puisque l’indice synthétique de la fécondité révélé  par le RGPH 2014 (2,21 enfants) est légèrement supérieur à celui estimé par l’Enquête Nationale Démographique à Passage Répété 2009-2010 (2,19 enfants) suite à un léger accroissement de la fécondité en milieu urbain (1,8 contre 2,01 enfants) (Figure 1).\r\n', 'Population & démographie', 'Publié', '2026-08-15', 'uploads/1786806597_note_niveau_et_tendance_de_la_fecondite_au_maroc_fr.docx', 1);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(14, 'ST-010', , 'Publication du rapport de la Région de Casablanca Settat sur les Objectifs de Développement Durable 2025', 'Le Haut-Commissariat au Plan publie le Rapport 2025 sur les réalisations en matière des Objectifs de Développement Durable au niveau de la région de Casablanca-Settat.\r\n\r\nCe rapport s’inscrit dans le cadre de la mission confiée au Haut-Commissariat au Plan visant à assurer le reporting et le suivi de la réalisation des Objectifs et des cibles de Développement Durable (ODD) aussi bien au niveau national que territorial.\r\n\r\nDeuxième du genre, après celui publié en décembre 2022 pour la région de Tanger Tétouan Al Hoceima, ce rapport s’inscrit dans la démarche du HCP visant à généraliser le reporting des réalisations en matière des ODD à l’ensemble des régions du Royaume.\r\n\r\nCe rapport dresse un état des lieux actualisé couvrant les différents programmes et stratégies engagés pour atteindre les 17 objectifs ODD à l’horizon 2030 au niveau de la région de Casablanca Settat, et renseigne sur les progrès accomplis ainsi que les défis et enjeux à relever. Ce rapport met également à la disposition des acteurs de développement territoriaux et des différents utilisateurs un tableau de bord permettant de comparer les réalisations de cette région dans le domaine des ODD avec celles atteintes au niveau national.\r\n\r\nFruit d’une démarche collaborative et inclusive, ce rapport a été élaboré en étroite concertation avec les acteurs institutionnels, notamment la Wilaya de la région, les provinces et préfectures, le Conseil Régional, les services déconcentrés de l\'État ainsi que le monde académi', 'Développement durable', 'Publié', '2026-08-05', 'uploads/1786806697_Objectifs_du_d__veloppement_durable__Rapport_R__gional_Casablanca_-_Settat_2025.pdf', 0);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(15, 'ST-011', , 'Note d’information à l’occasion de la journée mondiale de l’enfance du 20 novembre 2017', 'Afin de promouvoir le respect et les droits des enfants, la communauté internationale célèbre le 20 novembre de chaque année la journée mondiale de l’enfance. Cette année, l\'UNICEF invite les enfants du monde entier « à prendre les commandes » dans les domaines de la politique, des médias, du sport, du divertissement, etc. afin d\'exprimer leur soutien aux millions d\'enfants qui ne sont pas scolarisés, qui sont déracinés ou qui ne bénéficient pas de protection sociale.\r\n\r\n\r\nNote d’information à l’occasion de la journée mondiale de l’enfance du 20 novembre 2017\r\nS’inscrivant dans ce contexte, le Haut Commissariat au Plan, présente la situation démographique, de scolarisation, d’activité, de santé et d’handicap des enfants de moins de 18 ans d’après les résultats du Recensement Général de la Population et de l’Habitat (RGPH) de 2014.\r\n\r\nL’EFFECTIF DES ENFANTS DE MOINS DE 18 ANS EN DIMINUTION D’ICI 2030\r\n\r\nEn 2014, les enfants de moins de 18 ans constituent près du tiers de la population marocaine (33,6%). Leur nombre a enregistré une légère augmentation de 0,2% passant de 11,08 millions en 2004 à près de 11,33 millions en 2014. 51% sont de sexe masculin et 49% de sexe féminin, et 55,9% des enfants résident en milieu urbain contre 44,1% en milieu rural. Ces enfants représenteraient 26,7% à l’horizon 2030, soit 10,5 millions. \r\n\r\nPRES DE 5000 ENFANTS DEJA MARIES AVANT 18 ANS\r\n\r\nLa majorité des enfants sont célibataires. Cependant, 0,8% des enfants en 2014, soit 48291 mineurs avaie', 'Développement durable', 'Publié', '2026-08-05', 'uploads/1786806884_note_journee_mondiale_de_l__enfance_ar.docx', 0);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(16, 'ST-012', , 'Note sur les principaux résultats de l’Enquête Nationale sur le Niveau de Vie des Ménages 2022-2023', 'Le Haut-Commissariat au Plan a mené une Enquête Nationale sur le Niveau de Vie des Ménages entre mars 2022 et mars 2023 auprès d’un échantillon de 18000 ménages, représentatif des catégories socioéconomiques et de toutes les régions du Royaume. Cette enquête de structure, qui fait suite à une enquête similaire en 2014 et une enquête partielle en 2019, fournit une vision actualisée des dynamiques socio-économiques qui caractérisent la société marocaine.  Il en ressort que structurellement le niveau de vie des ménages s’améliore, sans que cette dynamique ne s’accompagne d’une réduction des inégalités. Les politiques de filets sociaux ont un impact tangible sur la réduction de la pauvreté, mais la vulnérabilité des couches sociales non ciblées par ces politiques, augmente. Ainsi, la part des ménages avec un risque de déclassement vers la pauvreté s’élargit, et, pour la première fois, concerne autant les milieux urbains que ruraux.  Le niveau de vie a nettement progressé entre 2014 et 2019, avec une décélération entre 2019 et 2022, période Covid  Entre 2014 et 2022, la dépense annuelle moyenne par ménage est passée de 76 317 DH à 83 713 DH à l’échelle nationale correspondant à 95 386 DH en milieu urbain et à 56 769 DH en milieu rural. Ramenée à l’échelle individuelle, la dépense annuelle moyenne par personne est passée de 15 876 DH en 2014 à 20 658 DH en 2022. Elle a ainsi progressé, aux prix constants, à un taux annuel moyen de 1,1% entre 2014 et 2022, passant de 3,1% entre', 'Revenu & conditions de vie', 'Publié', '2026-08-05', 'uploads/1786807249_Pdsaf.docx', 0);
INSERT INTO `statique` (`id`, `ID_stat`, `Image_stat`, `Titre_stat`, `description_stat`, `Categorie_stat`, `Statut_stat`, `date_stat_pub`, `link_files`, `nbre_stat`) VALUES
(17, 'ST-013', , 'Les Cahiers du Plan N° 55 - Décembre 2022', 'Ce numéro 55 des Cahiers du Plan propose deux dossiers. Le premier est consacré à une analyse économique de l’environnement et des ressources naturelles. Le second traite de questions d’inégalités sociales et de développement en lien avec les politiques éducatives et la qualité de l’éducation.\r\n \r\n\r\nEn effet, trente ans après l’édition du premier rapport Meadows du Club de Rome en 1972 alertant sur le fait que les capacités de la planète risqueraient d’être dépassées, la même équipe confirme en 2002 que plusieurs limites ont effectivement été atteintes. Ce constat a conduit plusieurs économistes à développer des théories de la décroissance. Si ce principe de la décroissance peut être discuté dans le cadre de pays développés, il ne peut en revanche être envisagé pour des pays en voie de développement comme le Maroc.\r\n \r\n\r\nCe présent numéro pose la problématique du développement dans un contexte de contrainte sur les ressources naturelles et humaines.\r\n \r\n\r\nLa connaissance est la seule ressource qui augmente avec le partage. Le secteur de l’éducation est donc un secteur qui a un potentiel de croissance infini et décorrélé avec la consommation de ressources naturelles. Ce potentiel est d’autant plus important que les indicateurs d’éducation au Maroc et en Afrique connaissent des potentiels d’amélioration significatifs, comme le démontre le second dossier.\r\n \r\n\r\nQuant à la gestion des ressources naturelles elles-mêmes, s’il existe des tensions sur la quantité de ressources exploi', 'Autres...', 'Publié', '2026-06-18', 'uploads/1786807174_Les_cahiers_du_plan_N___55_-_D__cembre_2022.pdf', 0);

